  // lpddr: channel = off[16:12] ^ off[21:17], off = a - LPDDR_BASE
  function automatic int phone_mesh_lpddr_channel(logic [31:0] a);
    logic [31:0] off = a - LPDDR_BASE;
    logic [4:0] c = off[16:12] ^ off[21:17];
    return int'(c);
  endfunction
  // channel-local address: the offset with the channel-select bits removed
  function automatic logic [31:0] phone_mesh_lpddr_local(logic [31:0] a);
    logic [31:0] off = a - LPDDR_BASE;
    return ((off >> 17) << 12) | (off & 32'h00000FFF);
  endfunction
  function automatic int dram_channel(logic [31:0] a); return phone_mesh_lpddr_channel(a); endfunction
  function automatic logic [31:0] dram_local(logic [31:0] a); return phone_mesh_lpddr_local(a); endfunction
  function automatic int phone_mesh_dram_channel(logic [31:0] a); return phone_mesh_lpddr_channel(a); endfunction
  function automatic logic [31:0] phone_mesh_dram_local(logic [31:0] a); return phone_mesh_lpddr_local(a); endfunction

  // address -> NoC slave port (S_DEF on a miss)
  function automatic int phone_mesh_decode(logic [31:0] a);
    if (a >= LPDDR_BASE && a - LPDDR_BASE < 33'(LPDDR_SIZE))
      return S_LPDDR_FIRST + phone_mesh_lpddr_channel(a);
    if (a >= BOOT_SRAM_BASE && a - BOOT_SRAM_BASE < BOOT_SRAM_SIZE) return S_BOOT_SRAM;
    if (a >= PERIPH_BASE && a - PERIPH_BASE < PERIPH_SIZE) return S_PERIPH;
    return S_DEF;
  endfunction

